class Solution:

	def countWays(self, N, S):
		mod = 10 ** 3 + 3
		dic = {}

		def solve(s, i, j, x):
			if i > j:
				return 0
			if i == j:
				if s[i] == x:
					return 1
				else:
					return 0
			temp = str(i) + ' ' + str(j) + ' ' + str(x)
			if temp in dic.keys():
				return dic[temp]
			k = i + 1
			ans = [0]
			while k < j:
				LT = solve(s, i, k - 1, 'T')
				LF = solve(s, i, k - 1, 'F')
				RT = solve(s, k + 1, j, 'T')
				RF = solve(s, k + 1, j, 'F')
				if s[k] == '&':
					if x == 'T':
						ans[0] = (ans[0] + LT * RT % mod) % mod
					else:
						ans[0] = (ans[0] + LT * RF % mod + LF * RT % mod + LF * RF % mod) % mod
				elif s[k] == '|':
					if x == 'T':
						ans[0] = (ans[0] + LT * RT % mod + LT * RF % mod + LF * RT % mod) % mod
					else:
						ans[0] = (ans[0] + LF * RF % mod) % mod
				elif s[k] == '^':
					if x == 'T':
						ans[0] = (ans[0] + LT * RF % mod + LF * RT % mod) % mod
					else:
						ans[0] = (ans[0] + LT * RT % mod + LF * RF % mod) % mod
				k += 2
			dic[temp] = ans[0] % mod
			return ans[0] % mod
		return solve(S, 0, N - 1, 'T')
